text:
{
  "items": [
    {
      "index": 1,
      "scene": "航天与科技科普",
      "angle": "给出某行星到太阳的距离（整十万数），要求写出该数包含多少个“十万”这一计数单位。"
    },
    {
      "index": 2,
      "scene": "资源与环保统计",
      "angle": "提供三个不同年份的废纸回收吨数，要求使用计算器快速求出这三年的回收总量。"
    },
    {
      "index": 3,
      "scene": "植物生长记录",
      "angle": "根据四株植物一周的生长高度数据，判断关于“最高植株”或“平均高度”的统计描述是否正确。"
    },
    {
      "index": 4,
      "scene": "家居装修与铺地",
      "angle": "已知房间长宽（整数）和每平方米地砖价格（两位小数），不计算结果，直接判断总价的小数位数。"
    },
    {
      "index": 5,
      "scene": "田径与体能测试",
      "angle": "给出小明五次跳绳的成绩，去掉一个最高分和一个最低分后，求剩余三次成绩的平均数。"
    },
    {
      "index": 6,
      "combo": "A",
      "scene": "地理与地图知识",
      "angle": "对比两条河流的长度（一条为整十万数，一条为万以内数），先分析大数的组成，再比较大小。",
      "roles": {
        "计数单位十万的认识": "将整十万数转化为以‘万’或具体数值形式，明确其量级",
        "万以内数比较大小": "在统一量级或位数后，执行具体的数值大小比较逻辑"
      }
    },
    {
      "index": 7,
      "combo": "A",
      "scene": "科学实验与测量",
      "angle": "给出光年距离的大数，要求在数位顺序表中定位‘十万位’，并说明该位数字表示的含义。",
      "roles": {
        "亿以上计数单位与十进制数位顺序表": "构建完整的数位框架，确定高位与低位的相对位置",
        "计数单位十万的认识": "精准识别特定数位，并解释该位置数字代表的实际数值意义"
      }
    },
    {
      "index": 8,
      "combo": "A",
      "scene": "社会人口统计",
      "angle": "给出两个城市的人口数（亿以内），先正确读出这两个数，再判断哪个人口更多。",
      "roles": {
        "亿以内数的读法": "将阿拉伯数字转换为中文读法，辅助理解数的大小层级",
        "亿以内数的大小比较": "依据位数和高位数字，判定两个大数的大小关系"
      }
    }
  ]
}
